// Leave Bureau and Payroll Bureau screen text in South Africa's official languages.
//
// English is the base and is authoritative. Anything a language omits falls back to English via the
// i18n fallbackLocale, so a partial translation degrades to readable English rather than to a raw
// key. af/zu/xh/st/tn/fr are solid; nso/ss/ve/ts/nr are a best-effort DRAFT and should be verified
// by a native speaker before go-live — the same standing caveat as finance.ts.
//
// Those five were absent entirely until now, which meant a Sepedi, siSwati, Tshivenda, Xitsonga or
// isiNdebele user read every Bureau screen in English while the rest of the product answered them
// in their own language. The fallback made that silent rather than broken, which is worse: nothing
// looked wrong, so nobody reported it.
//
// Leave vocabulary is deliberately consistent with the existing `leave_import` namespace in
// modules/*.json, because a bureau agent who sees "Ukungenisa" on one screen and something else on
// the next will reasonably assume they are different things.
//
// Exposed under the `bureau` namespace, e.g. t('bureau.imports.title').

// Two levels are the norm — `bureau.emp.add_employee` — but a screen that groups its own labels
// (the dashboard's work queues) nests one deeper rather than flattening into `queues_blocked`,
// which reads as a namespace in the code and as noise everywhere else.
type Leaf = string | Record<string, string>
type Bureau = Record<string, Record<string, Leaf>>

